// src/data/heroBg.ts
// ------------------------------------------------------------------
// PHASE 18 / S2 — resolves full-bleed hero background variants.
// Manifest is generated by tools/optimize-hero-images.mjs (build-time,
// git-ignored). Missing manifest => plain <img> fallback, no build break.
// ------------------------------------------------------------------
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

type Variant = { width: number; avif: string; webp: string };
type Entry = { width: number; height: number; dir: string; variants: Variant[] };

const SIZES = '100vw';
const MANIFEST_REL = 'src/data/hero-manifest.json';

let cache: Record<string, Entry> | null = null;
let warned = false;

function manifest(): Record<string, Entry> {
  if (cache) return cache;
  try {
    cache = JSON.parse(readFileSync(join(process.cwd(), MANIFEST_REL), 'utf8'));
  } catch {
    cache = {};
    if (!warned) {
      warned = true;
      console.warn(
        `[heroBg] ${MANIFEST_REL} not found — heroes render the original JPEG only. ` +
          'Run `node tools/optimize-hero-images.mjs` to generate variants.'
      );
    }
  }
  return cache as Record<string, Entry>;
}

export type HeroBg = {
  width: number;
  height: number;
  avifSrcset: string;
  webpSrcset: string;
  sizes: string;
};

export function getHeroBg(src?: string | null): HeroBg | null {
  if (!src) return null;
  const entry = manifest()[src];
  if (!entry || !entry.variants || entry.variants.length === 0) return null;
  const avifSrcset = entry.variants.map((v) => `${entry.dir}/${v.avif} ${v.width}w`).join(', ');
  const webpSrcset = entry.variants.map((v) => `${entry.dir}/${v.webp} ${v.width}w`).join(', ');
  return { width: entry.width, height: entry.height, avifSrcset, webpSrcset, sizes: SIZES };
}
